SECRET_V1 = "ab" * 32
SECRET_V2 = "cd" * 32
ISSUER = "issuer-a"
ZERO_HASH = "0" * 64
MOMENT = 7


def compact(obj):
    return json.dumps(
        obj, ensure_ascii=False, sort_keys=True, separators=(",", ":")
    ).encode("utf-8")


def sign_payload(payload, secret):
    return hmac.new(
        bytes.fromhex(secret), compact(payload), hashlib.sha256
    ).hexdigest()


def make_checkpoint(payload, secret):
    return compact(
        {"payload": payload, "signature": sign_payload(payload, secret)}
    )


def keyring_v1(secret=SECRET_V1, revoked=False, not_before=0,
               not_after=10 ** 9, version=1):
    return {
        ISSUER: [
            {
                "version": version,
                "secret": secret,
                "notBefore": not_before,
                "notAfter": not_after,
                "revoked": revoked,
            }
        ]
    }


def make_ticket(paths, nonce="nonce-1", secret=SECRET_V1, issuer=ISSUER,
                key_version=1):
    payload = {
        "issuer": issuer,
        "keyVersion": key_version,
        "nonce": nonce,
        "notBefore": 0,
        "notAfter": 10 ** 9,
        "paths": list(paths),
    }
    return compact(
        {"payload": payload,
         "signature": sign_payload(payload, secret)}
    )


def cursor_of(result):
    return {
        "digest": result["digest"],
        "next": result["lastSeq"],
        "tail": result["tail"],
    }


